#include <bits/stdc++.h>

using namespace std;
using ll = long long;

ll get(const string& s) {
    ll product = 1;
    for (char c : s) {
        product *= c - '0';
    }
    return product;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    string s = to_string(n);
    ll res = get(s);

    if (n > 0) {
        ll power = 1;
        for (int i = 1; i < static_cast<int>(s.size()); ++i) {
            power *= 9;
        }
        res = max(res, power);
    }

    for (int i = static_cast<int>(s.size()) - 1; i != 0; --i) {
        int j = i - 1;
        while (j >= 0 && s[j] == '0') {
            --j;
        }

        if (j < 0) {
            break;
        }

        --s[j];
        ++j;
        while (j <= i) {
            s[j] = '9';
            ++j;
        }

        res = max(res, get(s));
    }

    cout << res << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll digitProduct(const string& s) {
    size_t first = s.find_first_not_of('0');
    if (first == string::npos) return 0;

    ll product = 1;
    for (size_t i = first; i < s.size(); ++i) {
        product *= s[i] - '0';
    }
    return product;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    ll result = digitProduct(s);

    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '0') continue;

        string candidate = s;
        --candidate[i];

        for (size_t j = i + 1; j < candidate.size(); ++j) {
            candidate[j] = '9';
        }

        result = max(result, digitProduct(candidate));
    }

    cout << result << '\n';
    return 0;
}

